<template><div class="shell"><DesignHeader title="活动案例" :back="true" @back="router.back()"></DesignHeader><main class="content page"><div class="filter-tabs"><Chip v-for="t in tabs" :key="t" :selected="activeTab===t" @click="activeTab=t">{{ t }}</Chip></div><p class="muted small">当前为门店内置素材，可收藏到本机，后续可直接复制使用。</p><article v-for="item in filteredItems" :key="item.id" class="list-card"><div><b>{{ item.title }}</b><p>{{ item.desc }}</p><small class="muted">{{ item.category }}</small></div><button class="icon-btn" :aria-pressed="item.saved" @click="toggleSaved(item)">{{ item.saved?'已收藏':'收藏' }}</button></article><EmptyState v-if="!filteredItems.length" title="暂无素材" /></main></div></template><script setup>
import EmptyState from '../components/EmptyState.vue'
import Chip from '../components/Chip.vue'

import DesignHeader from '../components/DesignHeader.vue'
import { computed, ref } from 'vue';import { useRouter } from 'vue-router';import { getStorage, setStorage } from '../utils/storage.js'
const router=useRouter();const tabs=['全部','活动方案','销售话术','成功案例'];const activeTab=ref('全部');const seed=[{id:'renewal',category:'活动方案',title:'节日焕新季',desc:'以旧换新专场活动话术'},{id:'reception',category:'销售话术',title:'高端定制接待',desc:'预约客户沟通流程'},{id:'birthday',category:'成功案例',title:'会员生日关怀',desc:'生日月专属权益模板'}];const savedIds=ref(readSaved());const items=computed(()=>seed.map(item=>({...item,saved:savedIds.value.includes(item.id)})));const filteredItems=computed(()=>activeTab.value==='全部'?items.value:items.value.filter(item=>item.category===activeTab.value));function readSaved(){try{const raw=JSON.parse(getStorage('dajin-activity-saved','[]'));return Array.isArray(raw)?raw:[]}catch{return []}}function toggleSaved(item){const next=new Set(savedIds.value);if(next.has(item.id))next.delete(item.id);else next.add(item.id);savedIds.value=[...next];setStorage('dajin-activity-saved',JSON.stringify(savedIds.value))}</script>
